problems.reference_solution:
import re
from collections import Counter

WORD = re.compile(r"[a-z]+(?:'[a-z]+)*")


def top_words(text, k):
    """Return the k most common (word, count) pairs, ties in order of first appearance."""
    return Counter(WORD.findall(text.lower())).most_common(k)

