import heapq
from datetime import datetime


def merge_logs(*logs):
    """Return the lines of all sorted logs, sorted by the moment of each line."""
    return list(heapq.merge(*logs, key=_moment))


def _moment(line):
    return datetime.fromisoformat(line.split(' ', 1)[0])

