problems.reference_solution:
import bisect


class Timeline:
    """Events at integer times, counted by range."""

    def __init__(self):
        self._times = []

    def add(self, time):
        bisect.insort(self._times, time)

    def count(self, start, end):
        return bisect.bisect_right(self._times, end) - bisect.bisect_left(self._times, start)

