problems.reference_solution:
import csv
import io
import json
import re


def csv_to_json(text):
    """Return the CSV records of text as a JSON list of objects."""
    records = csv.DictReader(io.StringIO(text))
    return json.dumps([{key: _value(field) for key, field in record.items()} for record in records])


def _value(field):
    if field == '':
        return None
    if re.fullmatch(r'-?[0-9]+', field):
        return int(field)
    return field

