import json

from solution import *


def _records(text):
    result = csv_to_json(text)
    assert isinstance(result, str), 'return a JSON string'
    return json.loads(result)


def test_example_1():
    """A quoted comma, a number and an empty value."""
    assert _records('name,age,city\nAnn,31,"Paris, France"\nBob,,Rome\n') == [
        {'name': 'Ann', 'age': 31, 'city': 'Paris, France'},
        {'name': 'Bob', 'age': None, 'city': 'Rome'},
    ]


def test_header_only():
    """No records: an empty list."""
    assert _records('a,b\n') == []


def test_key_order():
    """Keys follow the header."""
    assert list(_records('z,a,m\n1,2,3')[0]) == ['z', 'a', 'm']


def test_numbers_and_strings():
    """Only whole numbers become numbers."""
    assert _records('v\n-12\n3.5\n1e3\n 7\n+4\n-\nabc') == [
        {'v': -12}, {'v': '3.5'}, {'v': '1e3'}, {'v': ' 7'}, {'v': '+4'}, {'v': '-'}, {'v': 'abc'},
    ]


def test_quotes_and_line_breaks():
    """Doubled quotes and a line break inside a quoted field."""
    text = 'note,n\n"She said ""hi""",1\n"two\nlines",2\n'
    assert _records(text) == [
        {'note': 'She said "hi"', 'n': 1},
        {'note': 'two\nlines', 'n': 2},
    ]


def test_unicode():
    """Text outside ASCII survives."""
    assert _records('name\nZoë\n東京') == [{'name': 'Zoë'}, {'name': '東京'}]


def test_many():
    """Ten thousand records."""
    text = 'id,square\n' + ''.join(f'{i},{i * i}\n' for i in range(10000))
    assert _records(text) == [{'id': i, 'square': i * i} for i in range(10000)]

