problems.reference_solution:
from itertools import groupby


def encode(text):
    """Return the runs of equal characters as (character, length) pairs."""
    return [(character, sum(1 for _ in run)) for character, run in groupby(text)]


def decode(runs):
    """Return the text that the (character, length) pairs describe."""
    return ''.join(character * length for character, length in runs)

